11-tipos-e-checagem.codigo:
// Exercicio 124 — Analise estatica
// Enunciado: escreva erros de proposito e confirme que o dataforge check os encontra.

// Este arquivo roda sem erros. Os problemas que o analisador encontraria
// estao descritos abaixo, em comentarios, para voce reproduzir.

action somar(a: Integer, b: Integer) -> Integer:
    yield a + b

steady LIMITE := 100

out somar(2, 3)
out LIMITE

// Cada linha abaixo, se descomentada, e apontada por 'dataforge check':
//
//   somar(1)              -> action 'somar' is missing argument(s): b
//   somar(1, 2, 3)        -> action 'somar' takes 2 argument(s) but 3 were given
//   somar("x", 2)         -> parameter 'a' expects Integer but got String
//   sommar(1, 2)          -> undefined action 'sommar'  (sugere 'somar')
//   LIMITE := 200         -> cannot reassign the steady constant 'LIMITE'
//   x: Intger := 1        -> unknown type 'Intger'      (sugere 'Integer')
//   out 1 + [2]           -> cannot add Integer and Cluster

// O que o analisador NAO impede: erros que so existem em tempo de execucao.
divisor := 0
monitor:
    out 10 / divisor
handle e:
    out "isso so aparece rodando:", e.message

assert somar(2, 3) is 5, "soma"
out "rode 'dataforge check' neste arquivo: zero erros"

13-desestruturacao.codigo:
// Exercicio 134 — Resto e spread
// Enunciado: colete o que sobra com ...resto e expanda colecoes com ...

// ...resto captura o que sobrou
primeiro, ...outros := [1, 2, 3, 4, 5]
out primeiro, outros
assert primeiro is 1, "cabeca"
assert outros is [2, 3, 4, 5], "cauda"

// O resto pode estar no meio
inicio, ...meio, fim := [1, 2, 3, 4, 5]
out inicio, meio, fim
assert meio is [2, 3, 4], "o meio"
assert fim is 5, "o ultimo"

// Resto vazio e valido
so_um, ...nada := [9]
assert nada is [], "resto pode ser vazio"

// Spread expande na construcao
a := [1, 2]
b := [3, 4]
juntos := [...a, ...b, 5]
out juntos
assert juntos is [1, 2, 3, 4, 5], "concatenacao com spread"

// Spread em vaults: o ultimo vence
padrao := {"tema": "claro", "fonte": 14}
usuario := {"tema": "escuro"}
final := {...padrao, ...usuario}
out final
assert final is {"tema": "escuro", "fonte": 14}, "usuario sobrescreve padrao"

// Spread em chamadas
action somar_tres(a, b, c):
    yield a + b + c

args := [10, 20, 30]
out somar_tres(...args)
assert somar_tres(...args) is 60, "argumentos expandidos"

// Copia rasa: o novo nao e o mesmo objeto
original := [1, 2, 3]
copia := [...original]
copia.append(4)
out original, copia
assert original is [1, 2, 3], "o original nao mudou"
assert copia is [1, 2, 3, 4], "a copia mudou"

// Exercicio 137 — Compreensao de vaults
// Enunciado: construa dicionarios com a mesma sintaxe, produzindo chave e valor.

nums := [1, 2, 3, 4, 5]

// Chave e valor a partir de uma fonte
quadrados := {n: n * n cycle n in nums}
out quadrados
assert quadrados[4] is 16, "chave 4 mapeia para 16"

// Filtrando
pares := {n: n * n cycle n in nums given n % 2 is 0}
out pares
assert len(pares.keys()) is 2, "so 2 e 4"

// Inverter um dicionario
originais := {"a": 1, "b": 2, "c": 3}
invertido := {originais[k]: k cycle k in originais.keys()}
out invertido
assert invertido[2] is "b", "valor virou chave"

// Indexar registros por um campo
pessoas := [
    {"id": 10, "nome": "Ana"},
    {"id": 20, "nome": "Bruno"}
]
por_id := {p["id"]: p["nome"] cycle p in pessoas}
out por_id
assert por_id[20] is "Bruno", "acesso direto por id"

// Contar ocorrencias
palavras := ["sol", "lua", "sol", "mar", "sol", "lua"]
distintas := unique(palavras)
contagem := {p: palavras.count(p) cycle p in distintas}
out contagem
assert contagem["sol"] is 3, "sol aparece 3 vezes"

// Normalizar chaves de entrada
bruto := {"  Nome ": "Ana", "IDADE": 30}
limpo := {k.trim().lower(): bruto[k] cycle k in bruto.keys()}
out limpo
assert "nome" in limpo, "chave normalizada"
assert limpo["idade"] is 30, "valor preservado"

16-modulos-e-projetos.codigo:
// Exercicio 152 — Imports seletivos e apelidos
// Enunciado: traga so os simbolos que voce usa, com o nome que preferir.

// Forma compacta: Modulo.{nomes}
adopt geometria.{area_circulo, PI}

out $"PI = {PI}"
out $"area = {round(area_circulo(1), 4)}"
assert round(area_circulo(1), 4) is 3.1416, "usado sem prefixo"

// Forma explicita, com apelido
adopt {realcar as destacar, linha} from textos

out destacar("titulo")
out linha("=", 24)
assert destacar("x") is "[x]", "apelido funciona"
assert linha("*", 3) is "***", "importado direto"

// Tambem vale para a stdlib
adopt Arcane.Math.{sqrt, factorial}
out $"sqrt(81) = {sqrt(81)}  5! = {factorial(5)}"
assert sqrt(81) is 9.0, "sqrt sem prefixo"
assert factorial(5) is 120, "factorial sem prefixo"

// Pedir um simbolo que o modulo nao exporta e erro claro
erro := ""
monitor:
    adopt geometria.{nao_existe}
handle e:
    erro := e.message
    out $"erro: {erro}"

assert "does not export" in erro, "a mensagem explica"
assert "area_circulo" in erro, "e lista o que existe"

// O modulo inteiro e o seletivo convivem
adopt geometria as geo
assert geo.PI is PI, "mesmo valor pelos dois caminhos"
out "os dois estilos coexistem"

// ════════════════════════════════════════════════════════════
//  Exercicio 157 — O que o 'check' pega ATRAVES do adopt
//
//  Num arquivo de 40 linhas, um erro aparece na primeira execucao.
//  Num sistema de 200 arquivos, a maioria das chamadas atravessa
//  modulo — e e ali que um erro sobrevive ate producao.
//
//  Este exercicio prova o que o analisador consegue provar antes de
//  rodar, e o que o faz calar. As duas metades importam: um falso
//  alarme ensina a ignorar mensagens.
// ════════════════════════════════════════════════════════════

adopt Arcane.OS as OS
adopt Arcane.IO as IO
adopt Arcane.Process as Proc

// ── Um projeto de dois modulos, escrito em disco ─────────────

// Uma subpasta PROPRIA, com nome unico.
//
// 'OS.temp_dir()' devolve a pasta temporaria do SISTEMA — compartilhada
// com todo processo da maquina. Escrever direto nela deixa lixo, e
// apaga-la no fim (a primeira versao deste exercicio fazia isso) seria
// destruir o temporario de todos os outros programas.
pasta := $"{OS.temp_dir()}/df-157-{randint(100000, 999999)}"
IO.mkdir(pasta)
IO.mkdir($"{pasta}/src")

IO.write($"{pasta}/src/loja.df", """record Produto:
    sku: String
    nome: String
    preco: Float

action criar(sku: String, nome: String) -> Produto:
    yield Produto(sku, nome, 0.0)

action com_preco(p: Produto, v: Float) -> Produto:
    yield p with {"preco": v}

action quantos() -> Integer:
    yield 0

action sem_tipo(x):
    yield x

relay Produto, criar, com_preco, quantos, sem_tipo
""")

// As mensagens saem em portugues: e o idioma padrao do runtime e do
// analisador. 'DF_IDIOMA=en' devolve o texto original, que e a forma que
// aparece nas buscas na internet.
action conferir(codigo):
    IO.write($"{pasta}/src/main.df", codigo)
    r := Proc.run(["dataforge", "check", $"{pasta}/src/main.df"])
    yield r["stdout"] + r["stderr"]

// ── 1. O campo errado, vindo de OUTRO arquivo ───────────────
//
// Isto depende do '-> Produto'. Uma acao que declara o retorno leva o
// tipo ATRAVES da fronteira, e o campo errado e acusado com sugestao.

saida := conferir("""adopt ./loja as L

p := L.criar("CAF", "Cafe")
out p.nomee
""")

assert "não tem o campo" in saida
assert "nomee" in saida
assert "quis dizer 'nome'" in saida

// ── 2. Aridade ──────────────────────────────────────────────

saida := conferir("""adopt ./loja as L

L.criar("CAF")
""")

assert "recebe 2 argumento" in saida
// E diz ONDE a acao foi declarada — no outro arquivo.
assert "loja.df" in saida

// ── 3. Simbolo que o modulo nao exporta ─────────────────────

saida := conferir("""adopt ./loja as L

L.apagar("CAF")
""")

assert "não tem 'apagar'" in saida
// A mensagem lista o que EXISTE: sem isso, a pessoa adivinha.
assert "criar" in saida

// ── 4. Tipo do argumento ────────────────────────────────────
//
// A aridade era conferida e o tipo nao: a superficie sabia QUANTOS
// argumentos, e nao O QUE cada um devia ser.

saida := conferir("""adopt ./loja as L

L.criar("CAF", 42)
""")

assert "espera String" in saida
assert "recebeu Integer" in saida

// ── 5. E DENTRO de uma acao, que e onde o codigo vive ───────
//
// A inferencia usa o escopo de QUEM CHAMA. Usar o escopo global fazia
// 'L.criar(sku, nome)' dentro de 'action f(sku, nome)' virar
// "Undefined name 'sku'" — 649 falsos alarmes num projeto de 252
// arquivos, um por cada uso de parametro numa chamada entre modulos.
//
// E os testes passavam: eles chamavam no nivel de topo, onde o escopo
// global e o certo.

saida := conferir("""adopt ./loja as L

action fazer(codigo: String, titulo: String):
    yield L.criar(codigo, titulo)

cycle i from 1 to 3:
    rotulo := $"item {i}"
    out L.criar(rotulo, rotulo).nome
""")

assert "sem erros" in saida

// E o erro de verdade, dentro da acao, continua sendo pego
saida := conferir("""adopt ./loja as L

action fazer(n: Integer):
    yield L.criar(n, "Cafe")
""")

assert "espera String" in saida
assert "recebeu Integer" in saida

// ── 6. O que o faz CALAR — e isto importa igual ─────────────
//
// Sem declaracao de tipo, nao ha o que provar. Inventar um tipo aqui
// daria o falso alarme que a politica proibe.

saida := conferir("""adopt ./loja as L

x := L.sem_tipo("qualquer coisa")
out x.campo_que_nao_existe
out L.sem_tipo(1), L.sem_tipo([1, 2])
""")

// 'sem erros' contem a palavra 'erro': conferir a ausencia dela
// contradiz a linha de baixo. O que importa e a AUSENCIA de
// diagnostico, e a saida do 'check' limpo diz "sem erros".
assert "sem erros" in saida

// ── 7. O codigo certo nao gera alarme nenhum ────────────────

saida := conferir("""adopt ./loja as L

p := L.criar("CAF", "Cafe")
out p.sku, p.nome, p.preco

q := L.com_preco(p, 29.9)
out q.preco

// um Integer serve onde se espera Float, como em toda a linguagem
r := L.com_preco(p, 30)
out r.preco

out L.quantos() + 1
""")

assert "sem erros" in saida

// ── 8. E um erro dentro do modulo IMPORTADO faz o check calar ─
//
// Um arquivo que nao compila e problema DELE, e o 'check' sobre ele
// vai dizer isso. Acusar o uso de um simbolo porque o outro arquivo
// esta quebrado seria culpar o inocente.

IO.write($"{pasta}/src/quebrado.df", "action f(:\n")
saida := conferir("""adopt ./quebrado as Q

Q.qualquer_coisa(1, 2, 3)
""")

// Nao acusa a chamada: a superficie de um arquivo que nao compila
// fica ABERTA, e o analisador volta a calar.
assert "não tem" not in saida

IO.remove_tree(pasta)
out "157 ok — o check atravessa o adopt"

17-tempo-e-sistema.codigo:
// Exercicio 161 — Sistema e ambiente
// Enunciado: consulte o sistema operacional e as variaveis de ambiente.

adopt Arcane.OS as OS
adopt Arcane.Text as Text

out Text.box("Sistema")
out $"sistema:    {OS.name()} {OS.release()}"
out $"arquitetura: {OS.arch()} ({OS.machine()})"
out $"maquina:    {OS.hostname()}"
out $"CPUs:       {OS.cpu_count()}"
out $"usuario:    {OS.user()}"

assert len(OS.name()) bigger 0, "o sistema tem nome"
assert OS.cpu_count() bigger_eq 1, "ao menos uma CPU"

// Detectar a plataforma
plataforma := "Windows" given OS.is_windows() otherwise "macOS" given OS.is_mac() otherwise "Linux" given OS.is_linux() otherwise "outro"
out $"plataforma: {plataforma}"

// info() traz tudo de uma vez
dados := OS.info()
assert "system" in dados, "info tem o sistema"
assert "cpus" in dados, "info tem as CPUs"

// Disco
uso := OS.disk_usage(".")
out ""
out Text.box("Disco")
out $"total: {uso.total_gb} GB"
out $"livre: {uso.free_gb} GB ({100 - uso.percent_used}% disponivel)"
assert uso.total_gb bigger 0, "o disco tem tamanho"

// Diretorios
out ""
out Text.box("Caminhos")
out $"atual: {OS.cwd()}"
out $"casa:  {OS.home()}"
out $"temp:  {OS.temp_dir()}"
out $"separador: '{OS.separator()}'"

// Variaveis de ambiente
out ""
out Text.box("Ambiente")
// Quantas HA nao se imprime: o numero depende da maquina, e mudaria
// entre duas execucoes se algo definisse uma variavel no meio. O que
// se pode afirmar e que ha alguma.
assert len(OS.env_names()) bigger 0
out $"PATH existe? {OS.has_env("PATH")}"
out $"inexistente com padrao: {OS.get_env("VARIAVEL_QUE_NAO_EXISTE", "(padrao)")}"

assert OS.get_env("SEM_ISSO_AQUI", "fallback") is "fallback", "padrao ao faltar"
assert OS.has_env("VARIAVEL_INEXISTENTE_XYZ") is no, "nao existe"

// Definir, ler de volta — e DESFAZER
//
// O ambiente e do PROCESSO, e um processo roda mais de um programa:
// 'dataforge test' cria um interpretador por arquivo. Deixar a
// variavel definida polui a execucao seguinte, e foi assim que este
// exercicio imprimia 77 variaveis na primeira vez e 78 na segunda —
// pego pelo teste que compara a saida com a compilacao ligada e
// desligada.
antes := len(OS.env_names())

OS.set_env("DATAFORGE_TESTE", "42")
assert OS.get_env("DATAFORGE_TESTE") is "42", "definida e lida"
assert len(OS.env_names()) is antes + 1, "uma a mais"
out $"definida: DATAFORGE_TESTE = {OS.get_env("DATAFORGE_TESTE")}"

assert OS.unset_env("DATAFORGE_TESTE"), "devolve yes: ela existia"
assert not OS.has_env("DATAFORGE_TESTE"), "e agora nao existe"
assert len(OS.env_names()) is antes, "o ambiente voltou ao que era"

// Remover o que nao existe devolve 'no', e nao levanta: remover e
// pedir um estado final, e nesse ponto ja nao importa se estava la.
assert OS.unset_env("NUNCA_EXISTIU_ISSO_AQUI") is no

// Encontrar um programa
out ""
python := OS.which("python3")
out $"python3 em: {python ?? "(nao encontrado)"}"

// Terminal
tam := OS.terminal_size()
out $"terminal: {tam.columns}x{tam.lines}"
assert tam.columns bigger 0, "largura do terminal"

// Exercicio 162 — Executando processos
// Enunciado: rode comandos externos e trate a saida.

adopt Arcane.Process as Proc
adopt Arcane.OS as OS

// ── O comando externo e onde o programa deixa de ser portatil ──
//
// 'echo' existe no Linux e no macOS como programa; no Windows ele e
// embutido do interpretador de comandos, e nao ha arquivo para rodar.
// 'cat' se chama 'more', e 'sleep' se chama 'timeout'.
//
// Por isso o primeiro passo de um programa que chama o sistema e
// decidir COM QUEM esta falando. O resto do exercicio e igual nos dois.

steady WINDOWS := OS.is_windows()
steady NL := char(10)

steady ECO := "cmd /c echo" given WINDOWS otherwise "echo"

// Comando que demora, para a demonstracao de tempo limite. O 'timeout'
// do Windows recusa entrada redirecionada e sai na hora; o 'ping' para
// o proprio computador espera de verdade nos dois sistemas.
steady DEMORA := "ping -n 6 127.0.0.1" given WINDOWS otherwise "sleep 5"

// run devolve stdout, stderr e o codigo de saida
r := Proc.run($"{ECO} ola do processo")
out $"saida:  {r.stdout.trim()}"
out $"codigo: {r.exit_code}"
out $"ok:     {r.ok}"

assert r.ok is yes, "o eco funciona"
assert r.exit_code is 0, "codigo zero"
assert r.stdout.trim() is "ola do processo", "a saida"

// capture pega so o stdout, ja limpo
out ""
out $"capture: '{Proc.capture($"{ECO} direto")}'"
assert Proc.capture($"{ECO} direto") is "direto", "capture"

// Comando inexistente nao derruba o programa
falhou := Proc.run("comando_que_nao_existe_xyz")
out ""
out $"inexistente -> codigo {falhou.exit_code}, ok={falhou.ok}"
assert falhou.ok is no, "falhou"
// 127 nos DOIS: a linguagem normaliza. O Windows levanta um erro do
// sistema em vez de devolver codigo, e 'Arcane.Process' traduz — quem
// escreve nao precisa saber de qual lado esta.
assert falhou.exit_code is 127, "o codigo de comando nao encontrado"

// check devolve so yes/no
out ""
out $"xyz existe?  {Proc.exists("comando_inexistente_xyz")}"
assert Proc.exists("comando_inexistente_xyz") is no, "o que nao existe"

// Argumentos com espacos: passe como lista, sem shell
//
// Sem lista, o espaco separaria em dois argumentos — e com um nome de
// arquivo vindo de fora, um espaco a mais vira uma falha de seguranca.
r2 := Proc.run([...ECO.split(" "), "texto com espacos"])
out ""
out $"lista: {r2.stdout.trim()}"

// A comparacao e por CONTEM, e nao por igual, de proposito: o 'cmd' do
// Windows reprocessa a linha e devolve as aspas junto com o texto. Isso
// nao enfraquece o teste — enfraqueceria se o argumento tivesse sido
// PARTIDO, e e exatamente isso que se esta cobrando. E e a melhor
// ilustracao de por que se passa lista: mesmo com lista, o que ha do
// outro lado ainda pode reinterpretar.
assert "texto com espacos" in r2.stdout, "a lista preserva o argumento"

// Enviar entrada para o processo
//
// 'sort' e um dos poucos que existe com o mesmo nome nos dois sistemas,
// e le da entrada padrao quando nao recebe arquivo.
r3 := Proc.run("sort", input_text := $"c{NL}a{NL}b{NL}")
ordenado := r3.lines >> morph l: l.trim() >> sift l: l isnt ""
out $"stdin ordenado: {ordenado}"
assert ordenado is ["a", "b", "c"], "a entrada padrao chegou e voltou ordenada"

// Encadear comandos: a saida de um vira a entrada do proximo
resultado := Proc.pipeline([$"{ECO} zebra", "sort"])
out ""
out $"pipeline: {resultado.stdout.trim()}"
assert resultado.stdout.trim() is "zebra", "a saida de um virou a entrada do outro"

// Tempo limite
lento := Proc.run(DEMORA, timeout := 1)
out ""
out $"com timeout: ok={lento.ok}"
assert lento.ok is no, "o comando estourou o tempo"

19-concorrencia.codigo:
// Exercicio 171 — Threads e paralelismo
// Enunciado: execute trabalho em segundo plano.

adopt Arcane.Time as Time

// Um bloco thread roda em segundo plano
resultados := []

thread:
    cycle i from 1 to 3:
        resultados.append($"A{i}")

thread:
    cycle i from 1 to 3:
        resultados.append($"B{i}")

// Espera as threads terminarem
wait 200

out $"itens produzidos: {len(resultados)}"
assert len(resultados) is 6, "as duas threads produziram"

// parallel roda cada instrucao em uma thread
adopt Arcane.Math as Math

saidas := []
parallel:
    saidas.append($"fatorial: {Math.factorial(12)}")
    saidas.append($"fibonacci: {Math.fibonacci(25)}")
    saidas.append($"primo: {Math.is_prime(9973)}")

wait 300
out ""
cycle s in sorted(saidas):
    out $"  {s}"
assert len(saidas) is 3, "tres tarefas"

// Medindo: trabalho concorrente
action trabalho(n):
    total := 0
    cycle i from 1 to n:
        total += i * i
    yield total

crono := Time.stopwatch()
crono.start()

sequencial := []
cycle n in [50000, 50000, 50000]:
    sequencial.append(trabalho(n))

tempo_seq := crono.stop()
out ""
out $"sequencial: {round(tempo_seq * 1000, 1)} ms"
assert len(sequencial) is 3, "tres resultados"

// Aviso importante: sem sincronizacao, atualizacoes se perdem
//
// O 'check' ACUSA as duas linhas abaixo — e esta certo. Aqui a corrida
// e o assunto do exercicio, e 'df: permitir' diz isso a ele. A regra e
// nomeada: um 'permitir' solto esconderia o erro seguinte.
contador := {"valor": 0}

thread:
    cycle _ in range(0, 1000):
        // df: permitir escrita-concorrente
        contador["valor"] := contador["valor"] + 1

thread:
    cycle _ in range(0, 1000):
        // df: permitir escrita-concorrente
        contador["valor"] := contador["valor"] + 1

wait 400

// O NUMERO nao e impresso — e ele que varia.
//
// Este exercicio existe para mostrar a corrida, e por isso o resultado
// dele e instavel de proposito: 2000 nesta maquina, 1847 no CI, outro
// numero na proxima execucao. O teste que compara a saida com a
// compilacao ligada e desligada roda o arquivo DUAS vezes e exige saida
// identica — e reprovou.
//
// Imprimir a instabilidade era a forma errada de ensina-la. A forma
// certa e AFIRMAR o que se sabe: o valor nunca passa do esperado,
// porque duas threads so podem perder incrementos, nunca inventar.
valor := contador["valor"]

assert valor smaller_eq 2000, "nunca passa: so se perde, nao se inventa"
assert valor bigger 0, "algo foi contado"

out ""
given valor smaller 2000:
    out "o contador veio MENOR que 2000: voce acabou de ver uma"
    out "condicao de corrida acontecer."
otherwise:
    out "o contador fechou em 2000 NESTA execucao — e sorte, nao"
    out "garantia. Na proxima, ou em outra maquina, pode nao fechar."

// ── E a saida, no mesmo arquivo ──────────────────────────────
//
// 'Conc.contador()' e atomico: o incremento acontece dentro de uma
// trava, e o numero fecha SEMPRE. Nao ha o que torcer.
adopt Arcane.Concurrent as Conc

atomico := Conc.contador()

thread:
    cycle _ in range(0, 1000):
        atomico.somar(1)

thread:
    cycle _ in range(0, 1000):
        atomico.somar(1)

wait 400

out ""
out $"com Conc.contador(): {atomico.valor()} — e sempre 2000"
assert atomico.valor() is 2000, "o contador atomico nao perde nada"

22-web-kiln.codigo:
// Exercicio 192 — O primeiro servidor
// Enunciado: declare um servidor com duas rotas e responda texto e HTML.

// 'server' declara a aplicacao; 'route' declara uma rota; 'respond'
// envia a resposta e encerra a rota, como 'yield' encerra uma acao.
// Nada sobe ainda: quem acende o forno e 'ignite'. Essa separacao e o
// que permite testar uma rota sem abrir socket nenhum.

adopt Kiln

server ola on 8080:
    route GET "/":
        respond html "<h1>Ola do Kiln</h1>"

    route GET "/ping":
        respond text "pong"

// Kiln.test executa o pedido direto na aplicacao, sem rede.
inicio := Kiln.test(ola, "GET", "/")
out "GET / ->", inicio["status"]
out inicio["body"]

pong := Kiln.test(ola, "GET", "/ping")
out "GET /ping ->", pong["body"]

assert inicio["status"] is 200, "a raiz responde 200"
assert pong["body"] is "pong", "o texto chega inteiro"
assert len(Kiln.routes(ola)) is 2, "duas rotas registradas"

// Um caminho que nao existe da 404 — sem precisar escrever isso.
assert Kiln.test(ola, "GET", "/nada")["status"] is 404, "404 automatico"

// Exercicio 193 — Parametros de caminho e query string
// Enunciado: leia :id do caminho e ?campo= da query.

// Dentro de uma rota voce ja tem seis nomes prontos: 'req', 'params',
// 'query', 'body', 'headers' e 'session'. Escrever
// req["params"]["id"] toda vez cansa; os atalhos existem por isso.

adopt Kiln

server api on 0:
    // ':id' casa um trecho; '*resto' casa o que sobrar, barras inclusive
    route GET "/usuarios/:id":
        respond json {"id": params["id"], "formato": query["f"] ?? "curto"}

    route GET "/arquivos/*caminho":
        respond json {"caminho": params["caminho"]}

curto := Kiln.test(api, "GET", "/usuarios/42")
out "sem query:", curto["body"]
assert curto["body"]["id"] is "42", "o parametro chega como texto"
assert curto["body"]["formato"] is "curto", "?? cobre a query ausente"

longo := Kiln.test(api, "GET", "/usuarios/42?f=longo")
out "com query:", longo["body"]["formato"]
assert longo["body"]["formato"] is "longo", "a query e lida"

fundo := Kiln.test(api, "GET", "/arquivos/notas/2026/marco.txt")
out "curinga:", fundo["body"]["caminho"]
assert fundo["body"]["caminho"] is "notas/2026/marco.txt", "'*' pega tudo"

// Exercicio 194 — Uma API RESTful completa
// Enunciado: os cinco verbos sobre um mesmo recurso, com os status certos.

// REST nao e so usar POST e GET: cada situacao tem seu status. 201 para
// criado, 204 para apagado sem corpo, 404 para inexistente, 405 quando
// o caminho existe mas o verbo nao. O Kiln entrega 404 e 405 sozinho;
// os outros sao decisao sua.

adopt Kiln
adopt Arcane.Concurrent as Conc

itens := [
    {"id": 1, "nome": "Martelo", "preco": 89.9},
    {"id": 2, "nome": "Bigorna", "preco": 450.0}
]

// A TRAVA que falta em quase todo CRUD em memoria.
//
// O Kiln atende um pedido por thread. Duas escritas simultanEas na
// mesma lista se atropelam: um PUT que le o indice 3 e escreve nele
// depois de um DELETE ter tirado o item 2 escreve no lugar errado.
//
// O 'check' avisa ('escrita-concorrente'), e a resposta e segurar a
// trava em volta da escrita — nao da leitura, que nao muda nada.
//
// 'mutex()' tem 'acquire' e 'release'; 'defer' garante o release mesmo
// se o corpo levantar, que e o unico jeito de nao deixar a trava presa.
trava := Conc.mutex()

action criar(dados):
    // 'len' e 'append' juntos: dois POST simultaneos leriam o mesmo
    // tamanho e dariam o mesmo id. A trava cobre os dois.
    trava.acquire()
    defer:
        trava.release()
    novo := {"id": len(itens) + 1, "nome": dados["nome"],
        "preco": dados["preco"]}
    itens.append(novo)
    yield novo

action trocar(i, novo):
    trava.acquire()
    defer:
        trava.release()
    itens[i] := novo

action apagar(i):
    trava.acquire()
    defer:
        trava.release()
    itens.pop(i)

action indice_de(id):
    cycle i from 0 to len(itens) - 1:
        given itens[i]["id"] is int(id):
            yield i
    yield -1

server loja on 0:
    route GET "/itens":
        respond json {"itens": itens, "total": len(itens)}

    route GET "/itens/:id":
        pedido := params["id"]
        i := indice_de(pedido)
        given i is -1:
            respond 404 json {"erro": $"item {pedido} nao existe"}
        respond json itens[i]

    route POST "/itens":
        // 'len' e 'append' juntos: dois POST simultaneos leriam o
        // mesmo tamanho e dariam o mesmo id. A trava cobre os dois.
        novo := criar(body)
        respond 201 json novo

    route PUT "/itens/:id":
        i := indice_de(params["id"])
        given i is -1:
            respond 404 json {"erro": "nao existe"}
        novo := {"id": int(params["id"]), "nome": body["nome"],
            "preco": body["preco"]}
        trocar(i, novo)
        respond json novo

    route DELETE "/itens/:id":
        i := indice_de(params["id"])
        given i is -1:
            respond 404 json {"erro": "nao existe"}
        apagar(i)
        respond 204

out "lista:", Kiln.test(loja, "GET", "/itens")["body"]["total"]

criado := Kiln.test(loja, "POST", "/itens", {"nome": "Tenaz", "preco": 65.5})
out "criado:", criado["status"], criado["body"]["nome"]
assert criado["status"] is 201, "criar devolve 201"

trocado := Kiln.test(loja, "PUT", "/itens/1", {"nome": "Marreta", "preco": 120})
out "trocado:", trocado["body"]["nome"]
assert trocado["body"]["nome"] is "Marreta", "PUT substitui"

apagado := Kiln.test(loja, "DELETE", "/itens/2")
out "apagado:", apagado["status"]
assert apagado["status"] is 204, "apagar nao devolve corpo"

assert Kiln.test(loja, "GET", "/itens/999")["status"] is 404, "404 do recurso"

// O caminho existe, o verbo nao: 405, com a lista do que e aceito.
recusa := Kiln.test(loja, "PATCH", "/itens/1")
out "verbo errado:", recusa["status"], recusa["headers"]["Allow"]
assert recusa["status"] is 405, "405, nao 404 — o caminho existe"

// Exercicio 195 — Paginas HTML com template
// Enunciado: renderize uma pagina a partir de um template com laco.

// 'render' le um arquivo da pasta declarada em 'views' e devolve HTML.
// A sintaxe do template e pequena de proposito: {{nome}} escreve,
// {{#lista}}…{{/lista}} repete, {{^lista}}…{{/lista}} cobre o vazio e
// {{&bruto}} nao escapa. Template que vira linguagem e codigo escondido
// onde ninguem procura.

adopt Kiln
adopt Arcane.IO as IO
adopt Arcane.OS as OS

// escreve o template no disco para o exercicio ser auto-contido
pasta := IO.join(OS.temp_dir(), "kilnviews")
IO.mkdir(pasta)  // sem isto, so roda se a pasta ja existir
IO.write_file(pasta + "/lista.html", """<!doctype html>
<title>{{titulo}}</title>
<h1>{{titulo}}</h1>
{{#produtos}}<article><h2>{{nome}}</h2><p>R$ {{preco}}</p></article>
{{/produtos}}
{{^produtos}}<p>Nada na forja.</p>{{/produtos}}""")

produtos := [
    {"nome": "Martelo", "preco": 89.9},
    {"nome": "Bigorna <de aco>", "preco": 450.0}
]

server site on 0:
    views pasta

    route GET "/":
        render "lista.html" with {"titulo": "Forja", "produtos": produtos}

    route GET "/vazio":
        render "lista.html" with {"titulo": "Vazio", "produtos": []}

pagina := Kiln.test(site, "GET", "/")
out pagina["body"]

assert "Martelo" in pagina["body"], "o laco do template repetiu"
// O escape e automatico: '<de aco>' nao vira tag.
assert "&lt;de aco&gt;" in pagina["body"], "HTML e escapado por padrao"
assert "<article>" in pagina["body"], "as tags do template ficam"

vazio := Kiln.test(site, "GET", "/vazio")
assert "Nada na forja" in vazio["body"], "{{^}} cobre a lista vazia"
assert "article" not in vazio["body"], "sem itens, sem artigos"

// Exercicio 196 — Middleware, autenticacao e limite de taxa
// Enunciado: proteja rotas e limite pedidos por IP.

// Middleware roda antes de toda rota. Se ele devolve uma resposta, a
// cadeia para ali — e assim que autenticacao e limite de taxa cortam o
// pedido antes de ele custar qualquer coisa. Se devolve void, o pedido
// segue, e o que ele guardou em req["state"] chega na rota.

adopt Kiln

usuarios := {"tk-ana": "Ana", "tk-bia": "Bia"}

action conferir(token):
    yield usuarios[token] ?? void

// A ordem importa. O limite vem primeiro: um pedido barrado pelo 'auth'
// nunca chegaria a ser contado, e quem esta martelando a porta com
// credenciais invalidas e justamente quem voce quer limitar.
server privado on 0:
    middleware Kiln.rate_limit(3, 60)
    middleware Kiln.auth(conferir)

    route GET "/eu":
        respond json {"usuario": req["state"]["user"]}

sem_token := Kiln.test(privado, "GET", "/eu")
out "sem credencial:", sem_token["status"], sem_token["headers"]["WWW-Authenticate"]
assert sem_token["status"] is 401, "sem token, 401"

errado := Kiln.test(privado, "GET", "/eu", void, {"Authorization": "Bearer nao-existe"})
out "token invalido:", errado["status"]
assert errado["status"] is 401, "token desconhecido tambem e 401"

certo := Kiln.test(privado, "GET", "/eu", void, {"Authorization": "Bearer tk-ana"})
out "autenticado:", certo["body"]["usuario"]
assert certo["body"]["usuario"] is "Ana", "o middleware passou o usuario adiante"

// O limite ja contou tres pedidos deste IP — inclusive os dois que o
// 'auth' recusou. O quarto nao passa, mesmo com credencial boa.
excedido := Kiln.test(privado, "GET", "/eu", void, {"Authorization": "Bearer tk-bia"})
out "quarto pedido:", excedido["status"]
assert excedido["status"] is 429, "o quarto pedido no minuto e recusado"
assert "Retry-After" in excedido["headers"], "e o cliente sabe quando voltar"

// Exercicio 198 — Subir o servidor de verdade
// Enunciado: acenda o forno, faca um pedido pela rede e apague.

// Ate aqui usamos Kiln.test, que executa a rota sem abrir socket. Agora
// o servidor de verdade: 'Kiln.serve' sobe em segundo plano e devolve a
// porta na hora (porta 0 deixa o sistema escolher uma livre — util em
// teste, onde uma porta fixa daria conflito). Em producao voce usa
// 'ignite', que bloqueia ate o Ctrl-C.

adopt Kiln
adopt Arcane.Web as Web
adopt Arcane.Concurrent as Conc

// Um CONTADOR ATOMICO, e nao uma variavel solta.
//
// O Kiln usa 'ThreadingHTTPServer': cada pedido roda numa thread. Dois
// pedidos ao mesmo tempo em 'visitas += 1' leem o mesmo valor e
// escrevem o mesmo — um incremento se perde.
//
// Medido: seis pedidos simultaneos numa rota que le, espera e escreve
// entregaram 1 de 6. O 'check' avisa isto ('escrita-concorrente'), e a
// resposta e uma linha.
visitas := Conc.contador()

server contador on 0:
    route GET "/":
        respond html "<h1>Forja</h1>"

    route GET "/contar":
        // 'somar' devolve o valor novo, dentro da trava: nao ha janela
        // entre ler e escrever.
        respond json {"visitas": visitas.somar(1)}

porta := Kiln.serve(contador, 0)
out "no ar na porta", porta

pagina := Web.get($"http://127.0.0.1:{porta}/")
out "pela rede:", pagina["status"], pagina["body"]
assert pagina["status"] is 200, "o servidor respondeu de verdade"
assert "Forja" in pagina["body"], "o HTML chegou inteiro"

Web.get($"http://127.0.0.1:{porta}/contar")
Web.get($"http://127.0.0.1:{porta}/contar")
terceira := Web.get($"http://127.0.0.1:{porta}/contar")
out "tres pedidos:", terceira["body"]
assert visitas.valor() is 3, "o estado do programa sobrevive entre pedidos"

numeros := Kiln.stats(contador)
out "estatisticas:", numeros["pedidos"], "pedidos,", numeros["rotas"], "rotas"
assert numeros["pedidos"] is 4, "quatro pedidos contados"
assert numeros["erros"] is 0, "nenhum erro"

Kiln.stop(contador)
out "forno apagado"

// Em um programa de verdade, a ultima linha seria:
//     ignite contador on 8080
// que sobe e fica servindo ate voce apertar Ctrl-C.

// Exercicio 199 — A API vista de fora: OpenAPI, Insomnia e curl
// Enunciado: exporte as rotas de um servidor Kiln para as ferramentas
// que quem consome a API de fato usa.

adopt Kiln
adopt Arcane.API as API

// ── Um servidor REST de verdade ──
//
// Os cinco metodos que um recurso REST tem. Repare que nada aqui e
// declarado DUAS vezes: nao ha um arquivo de documentacao ao lado
// dizendo o que as rotas sao. As rotas sao a fonte da verdade.

server Loja on 8080:
    route GET "/produtos":
        respond json {"produtos": [], "total": 0}

    route POST "/produtos":
        respond json {"criado": yes}

    route GET "/produtos/:id":
        respond json {"id": params["id"]}

    route PATCH "/produtos/:id":
        respond json {"alterado": params["id"]}

    route DELETE "/produtos/:id":
        respond json {"removido": params["id"]}

steady CONF := {
    "titulo": "API da Loja",
    "versao": "2.0.0",
    "base": "https://api.loja.com"
}

// ── 1. O que existe ──

resumo := API.resumo(Loja)
out $"rotas: {resumo["rotas"]}"
out $"metodos: {resumo["metodos"]}"
out $"com parametro: {resumo["com_parametro"]}"

assert resumo["rotas"] is 5, "cinco rotas"
assert resumo["com_parametro"] is 3, "tres usam:id"

// ── 2. OpenAPI, para o Swagger e para gerar cliente ──

adopt Arcane.Serialization as Serde

texto := API.openapi(Loja, CONF)
documento := Serde.from_json(texto)

out ""
out $"openapi: {documento["openapi"]}"
out $"titulo:  {documento["info"]["title"]}"
out $"caminhos: {documento["paths"].keys()}"

assert documento["openapi"] is "3.1.0", "OpenAPI 3.1"
assert "/produtos/{id}" in documento["paths"].keys(), "o:id virou {id}"

// O parametro de caminho e DECLARADO. Sem isso, o Swagger trata ':id'
// como parte literal do caminho, e o cliente gerado bate numa URL que
// nao existe.
parametro := documento["paths"]["/produtos/{id}"]["get"]["parameters"][0]
out $"parametro: {parametro["name"]} em {parametro["in"]}"
assert parametro["name"] is "id", "o parametro se chama id"

// ── 3. Insomnia, para testar a mao ──

colecao := Serde.from_json(API.insomnia(Loja, CONF))
pedidos := colecao["resources"] >> sift r: (r["_type"] ?? "") is "request"

out ""
out $"requisicoes: {len(pedidos)}"
out $"primeira: {pedidos[0]["method"]} {pedidos[0]["url"]}"

assert len(pedidos) is 5, "uma requisicao por rota"

// '{{ id }}' e o que o Insomnia reconhece como variavel. Deixar ':id'
// cru daria uma requisicao que bate literalmente em '/produtos/:id'.
com_variavel := pedidos >> sift p: "{{ id }}" in p["url"]
assert len(com_variavel) is 3, "as tres rotas com :id viraram variavel"

// ── 4. curl, para o README ──

comandos := API.curl(Loja, CONF)
out ""
out comandos.lines()[0]
out comandos.lines()[1]

assert comandos.count("curl ") is 5, "um curl por rota"
assert "https://api.loja.com" in comandos, "a base configurada"

// ── 5. Markdown, para a documentacao do projeto ──

tabela := API.markdown(Loja, CONF)
assert "| `GET` | `/produtos` |" in tabela, "a tabela de rotas"
assert "# API da Loja" in tabela, "o titulo"

out ""
out "ok"

23-dados-e-planilhas.codigo:
// Exercicio 200 — Gravar e ler uma planilha
// Enunciado: transforme uma lista de vaults num .xlsx e leia de volta.

// Um .xlsx e um ZIP de arquivos XML. O Arcane.Excel escreve e le esse
// formato sem nenhuma dependencia externa — o arquivo abre no Excel, no
// LibreOffice e no Google Sheets.

adopt Arcane.Excel as Xls
adopt Arcane.OS as OS
adopt Arcane.IO as IO

vendas := [
    {"produto": "Martelo", "qtd": 12, "preco": 89.9},
    {"produto": "Bigorna", "qtd": 3, "preco": 450.0},
    {"produto": "Tenaz", "qtd": 27, "preco": 65.5}
]

// Quando os dados sao vaults, o cabecalho sai das chaves — em negrito,
// com a primeira linha congelada e a largura ajustada ao conteudo.
Xls.quick(IO.join(OS.temp_dir(), "vendas.xlsx"), vendas, "Vendas")
out "planilha gravada"

livro := Xls.read(IO.join(OS.temp_dir(), "vendas.xlsx"))
out "abas:", Xls.sheets(livro)
out "tamanho:", Xls.dims(livro, "Vendas")

linhas := Xls.rows(livro, "Vendas")
out "cabecalho:", linhas[0]
out "primeira linha:", linhas[1]

assert linhas[0] is ["produto", "qtd", "preco"], "o cabecalho veio das chaves"
assert linhas[1][1] is 12, "o numero voltou numero, nao texto"

// 'records' devolve vaults de novo, usando a linha de cabecalho.
de_volta := Xls.records(livro, "Vendas")
assert len(de_volta) is 3, "tres registros"
assert de_volta[0]["produto"] is "Martelo", "ida e volta sem perda"

// Uma coluna inteira, pelo titulo.
assert Xls.column(livro, "Vendas", "qtd") is [12, 3, 27], "coluna pelo nome"

24-banco-de-dados.codigo:
// Exercicio 208 — Relacoes, e o problema do N+1
// Enunciado: carregue os pedidos de cem usuarios em duas consultas.

// Buscar cem usuarios e ler 'usuario.pedidos' de cada um faz cento e
// uma consultas. Isso nao aparece em desenvolvimento, com tres linhas
// na tabela, e derruba a producao com dez mil. E o bug de ORM mais
// comum que existe.

adopt Forge

db := Forge.conectar(":memory:")

Usuario := Forge.modelo("Usuario", {
        "id": {"tipo": "Serial"},
        "nome": {"tipo": "Texto", "obrigatorio": yes}
    }, {"conexao": db})

Pedido := Forge.modelo("Pedido", {
        "id": {"tipo": "Serial"},
        "usuario_id": {"tipo": "Inteiro", "indice": yes},
        "total": {"tipo": "Real", "padrao": 0}
    }, {"conexao": db})

Usuario.tem_muitos("pedidos", "Pedido")
Pedido.pertence_a("usuario", "Usuario")
Forge.migrar_tudo(db)

ana := Usuario.criar({"nome": "Ana"})
bia := Usuario.criar({"nome": "Bia"})
cid := Usuario.criar({"nome": "Cid"})

Pedido.criar({"usuario_id": ana["id"], "total": 100.0})
Pedido.criar({"usuario_id": ana["id"], "total": 50.0})
Pedido.criar({"usuario_id": bia["id"], "total": 20.0})

// A relacao NAO carrega sozinha ao ser lida — ou voce pede, ou ela
// nao vem. Ler uma relacao nao carregada devolveria void em vez de
// funcionar devagar.
com_pedidos := Usuario.com(Usuario.todos(), "pedidos")

cycle u in com_pedidos:
    out u["nome"], "tem", len(u["pedidos"]), "pedido(s)"

assert len(com_pedidos[0]["pedidos"]) is 2, "Ana tem dois"
assert len(com_pedidos[1]["pedidos"]) is 1, "Bia tem um"
assert len(com_pedidos[2]["pedidos"]) is 0, "Cid nao tem nenhum"

// Do outro lado: cada pedido conhece o dono
com_dono := Pedido.com(Pedido.todos(), "usuario")
assert com_dono[0]["usuario"]["nome"] is "Ana", "o pedido sabe de quem e"

// Somar por usuario, sem laco aninhado
total_da_ana := Forge.de(db, "pedidos").onde("usuario_id", ana["id"]).somar("total")
assert total_da_ana is 150.0, "100 + 50"

// Uma relacao que nao existe avisa, e lista as que existem
monitor:
    Usuario.com(Usuario.todos(), "inventada")
    assert no, "devia ter recusado"
handle SchemaError as e:
    out "recusado:", e.message
    assert "inventada" in e.message, "a mensagem nomeia o erro"

out "ok"

// Exercicio 209 — Migracoes
// Enunciado: evolua o esquema sem perder o que ja esta gravado.

// Duas formas. A simples compara o modelo com a tabela; a completa usa
// passos numerados, com historico NO BANCO — um arquivo versionado diz
// o que deveria ter rodado, a tabela diz o que rodou.

adopt Forge

db := Forge.conectar(":memory:")

// ── A forma simples: a diferenca ──

U := Forge.modelo("Usuario", {
        "id": {"tipo": "Serial"},
        "nome": {"tipo": "Texto", "obrigatorio": yes}
